import math

def is_power_of_2(n):
    """Checks if n is a power of 2 (and n > 0)."""
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

def get_exponent(n):
    """Returns the exponent A such that n = 2^A. Assumes n is a power of 2."""
    if n <= 0 or not is_power_of_2(n):
        return None
    return n.bit_length() - 1

def search_solutions(M_limit, N_limit):
    solutions = []
    print(f"Starting search for m, n > 5 up to {M_limit}x{N_limit}...")

    for m in range(6, M_limit + 1):
        for n in range(6, N_limit + 1):
            # Condition 1: m^2 + n = 2^A
            S_A = m*m + n
            A = get_exponent(S_A)

            if A is None or A < 2:
                continue

            # Condition 2: m + n^2 = 2^B
            S_B = m + n*n
            B = get_exponent(S_B)

            if B is None or B < 2:
                continue

            # Found a solution
            solutions.append({'m': m, 'n': n, 'p': 2, 'A': A, 'B': B})
            print(f"Found solution: (m={m}, n={n}, p=2, A={A}, B={B})")

    return solutions

# Set search limits: m, n up to 30
M_LIMIT = 30
N_LIMIT = 30
solutions = search_solutions(M_LIMIT, N_LIMIT)

if solutions:
    print("\n--- Summary ---")
    for sol in solutions:
        print(f"Triple: ({sol['m']}, {sol['n']}, {sol['p']}) Sum: {sol['m'] + sol['n'] + sol['p']}")
else:
    print("\nNo solutions found in the defined range.")
